// Mount the actual panel with isolated services and expose its existing closure for deterministic state selection.
async function panel(options = {}) {
  const window = openPage(JSDOM, '<form><input id="a"><input id="b"><input id="c"></form>');
  const {document} = window, events = [], messages = [], listeners = [];
  const fields = ['a', 'b', 'c'].map(id => ({el: document.getElementById(id), label: id, required: true, filled: false}));
  let now = 10000;
  window.Date.now = () => now;
  window.setInterval = () => 1;
  window.setTimeout = () => 1;
  window.MutationObserver = class { observe() {} };
  window.chrome = {runtime: {id: 'test', getManifest: () => ({version: '0.9.test'}), onMessage: {addListener: fn => listeners.push(fn)},
    sendMessage: async message => { messages.push(plain(message)); events.push(['send', plain(message)]); return message.type === 'panelLocale' ? {locale:'en',messages:catalogs.en,english:catalogs.en} : {ok: true}; }},
  storage: {local: {get: async () => ({}), set: async () => {}}}};
  for (const name of ['Required', 'ReadBack', 'TitleAbove', 'GroupTitle']) window[`__jobadabra${name}`] ||= {};
  window.__jobadabraPanelForm = {KNOCKOUT: /permit/i, AGREE: /agree/i, fields: () => fields,
    find: () => fields[0], flash: el => events.push(['flash', el.id])};
  window.__jobadabraPanelWritten = {start: () => ({update: list => events.push(['written', list.map(f => f.el.id)]), review: f => events.push(['review', f.el.id])})};
  window.__jobadabraPanelLearn = {start: () => ({reportMisses() {}, showMine() {}})};
  window.__jobadabraOverlay = {on: () => events.push(['overlay', true]), off: () => events.push(['overlay', false])};
  window.__jobadabraClaude = {mount() {}, render: facts => events.push(['claude', plain(facts)])};
  // Load real markup/copy and any drawing helpers through the production classic-script list.
  const mocked = ['panel-form.js', 'panel-learn.js', 'panel-written.js', 'panel-overlay-fx.js', 'panel-overlay.js', 'panel-report.js'];
  for (const file of PANEL_FILES.filter(file => file !== 'review.js' && !mocked.includes(file))) window.eval(read(file));
  const hook = `window.__renderTest = {render, showStep, endStep, stoppedHere, setOpen,
    set: state => { ({moved = false, movedTab = null, open = true, job = null, session = null, connection = null, build = null,
      claudeAsk = {}, filling = false, userMoved = true, cv = null, tipFor = null, coverLetterStatus = null,
      stopped = false, stuckSince = 0, stepAt = 0, lastStuck = '', applyWorking = false,
      markStepWords = '', workerStep = '', filledOnce = false, stepped = false} = state); },
    state: () => ({counts, shown: shown.map(f => f.el.id), lastStuck, stuckSince, markStepWords, tipFor, filledOnce})};`;
  const source = read('review.js').replace('  const soon = ', `${hook}\n  const soon = `).replace('  sync();\n  }', '  }');
  assert.ok(source.includes(hook), 'closure hook must attach before the observer');
  window.eval(source);
  await flush();
  const api = window.__renderTest;
  assert.ok(api);
  // No automatic sync runs: the host is obtained from a first render, then each case starts clean.
  document.documentElement.setAttribute('data-jobadabra-page', 'form');
  api.set({}); api.render();
  const mounted = document.getElementById('jobadabra-review-host');
  events.length = 0; messages.length = 0;
  const root = mounted.shadowRoot;
  // State flags normally drive this card via setOpen; keep it consistent without adding an extra render.
  api.set(options.state || {});
  root.querySelector('.card').hidden = options.state?.open === false;
  if (options.fields) { fields.length = 0; fields.push(...options.fields(document)); }
  for (const [name, value] of Object.entries(options.attrs || {})) {
    if (value === null) document.documentElement.removeAttribute(`data-jobadabra-${name}`);
    else document.documentElement.setAttribute(`data-jobadabra-${name}`, value);
  }
  options.prepare?.({window, document, root, api, fields});
  events.length = 0; messages.length = 0;
  return {window, document, root, host: mounted, api, fields, events, messages, listeners, advance: ms => { now += ms; }, close: () => window.close()};
}

// Serialize every element/attribute/text node, plus the public result and the ordered effects of one draw.
function capture(p, result) {
  const {list, ...rest} = result || {};
  return {dom: createHash('sha256').update(p.host.outerHTML + p.root.innerHTML).digest('hex'),
    connected: p.host.isConnected, result: result === null ? null : {...plain(rest), list: list.map(f => f.el.id)},
    state: plain(p.api.state()), events: plain(p.events)};
}

const baseFields = (document, extra = []) => ['a', 'b', 'c'].map((id, i) => ({el: document.getElementById(id), label: id, required: true, filled: false, ...extra[i]}));
const allFilled = document => baseFields(document, [{filled: true}, {filled: true}, {filled: true}]);
const account = value => ({document}) => { const box = document.getElementById('a'); box.type = 'password'; box.value = value; };
const cases = {
  left: {}, collapsed: {state: {open: false}}, ready: {fields: allFilled},
  empty: {fields: () => []}, optional: {fields: d => baseFields(d, [{required: false}, {required: false}, {required: false}])},
  small: {fields: d => baseFields(d).slice(0, 2)},
  'small-needs': {fields: d => baseFields(d).slice(0, 1), attrs: {needs: '1'}},
  'small-step': {fields: () => [], prepare: p => p.api.showStep('Reading the form…')},
  'small-mark': {fields: () => [], state: {applyWorking: true}, attrs: {page: 'reading'}},
  'password-empty': {prepare: account('')}, 'password-filled': {prepare: account('secret')},
  'password-refill': {prepare: p => { account('secret')(p); p.document.getElementById('a').setAttribute('data-jobadabra-filled', '1'); }},
  'password-pressed': {attrs: {'account-pressed': '1'}, prepare: p => { account('secret')(p); p.document.getElementById('a').setAttribute('data-jobadabra-filled', '1'); }},
  'password-hidden': {prepare: p => { account('')(p); p.document.getElementById('a').hidden = true; }},
  'account-ready': {fields: allFilled, prepare: account('secret')},
  'account-sign-up': {fields: allFilled, attrs: {'account-step': 'sign_up'}, prepare: account('secret')},
  'account-sign-in': {fields: allFilled, attrs: {'account-step': 'sign_in'}, prepare: account('secret')},
  'needs-ready': {fields: allFilled, attrs: {needs: '1'}}, 'needs-words': {attrs: {needs: 'Solve this challenge'}},
  moved: {fields: allFilled, state: {moved: true, movedTab: 4}}, 'moved-invalid-tab': {state: {moved: true, movedTab: '4'}},
  'night-ready': {attrs: {night: '1'}, fields: allFilled}, 'night-company': {attrs: {night: '1'}, state: {job: {company: 'Example'}}},
  'job-applied': {state: {job: {title: 'Engineer', company: 'Example', stage: 'Applied'}}},
  'job-other': {state: {job: {title: 'Engineer', stage: 'Saved'}, session: {company: 'Session Co'}}},
  'session-title': {state: {session: {title: 'Session role', company: 'Session Co'}}},
  'session-running': {state: {session: {live: true, status: 'running'}}},
  'session-note': {state: {session: {live: true, status: 'running', note: 'typing'}}},
  'session-input': {state: {session: {live: true, status: 'input'}}},
  'session-done': {state: {session: {status: 'done'}}}, 'session-form': {state: {session: {kind: 'form', status: 'done'}}},
  'session-inactive': {state: {session: {status: 'input'}}}, filling: {state: {filling: true}},
  'filling-ready': {fields: allFilled, state: {filling: true}}, 'filling-needs': {attrs: {needs: '1'}, state: {filling: true}},
  stopped: {state: {stopped: true}}, 'stuck-idle': {state: {session: {stuck: 'Need help'}}},
  'stuck-running': {state: {session: {stuck: 'Old', live: true, status: 'running'}}},
  'stuck-input': {state: {session: {stuck: 'Old', live: true, status: 'input'}}},
  'stuck-unchanged': {state: {session: {stuck: 'Same'}, lastStuck: 'Same', stuckSince: 1}},
  'stuck-cleared': {state: {session: {}, lastStuck: 'Old', stuckSince: 1}},
  'stuck-new-step': {state: {session: {stuck: 'Same'}, lastStuck: 'Same', stuckSince: 1, stepAt: 5}},
  'needs-working': {attrs: {needs: '1'}, state: {applyWorking: true}, prepare: p => p.api.showStep('Filling…')},
  'stopped-working': {state: {applyWorking: true, stopped: true}, prepare: p => p.api.showStep('Filling…')},
  'mark-start': {attrs: {page: 'posting'}, state: {applyWorking: true, open: false, userMoved: false}},
  'mark-unchanged': {attrs: {page: 'reading'}, state: {applyWorking: true, markStepWords: 'Reading this page…'}},
  'mark-ended-worker': {state: {markStepWords: 'Reading this page…', workerStep: 'Filling…'}},
  'mark-ended-fill': {state: {markStepWords: 'Reading this page…', filling: true}},
  'mark-ended-idle': {state: {markStepWords: 'Reading this page…'}},
  'rows-special': {state: {filledOnce: true}, fields: d => baseFields(d, [
    {label: 'Agree to terms', category: 'legal'}, {label: 'Work permit'}, {label: '', draft: 'outline'}])},
  'rows-ai': {state: {session: {status: 'done'}}, fields: d => baseFields(d, [
    {label: 'Long '.repeat(40), required: false, ai: true}, {label: 'Written', required: false, draft: 'answer'}, {label: 'Changed', required: false, changed: true, category: 'knockout'}])},
  'one-left': {fields: d => baseFields(d, [{filled: true}, {filled: true}]), state: {filledOnce: true}},
  'rows-limit': {fields: d => Array.from({length: 33}, (_, i) => ({el: d.getElementById('a'), label: `Field ${i}`, required: true, filled: false, category: i === 32 ? 'knockout' : ''})), state: {filledOnce: true}},
  connected: {state: {connection: {connected: true, app: true}}},
  'connected-session': {state: {connection: {connected: true, app: true}, session: {id: 's'}}},
  worker: {state: {connection: {connected: true, app: false}}}, offline: {state: {connection: {connected: false, why: 'App closed'}}},
  'offline-default': {state: {connection: {connected: false}}},
  build: {state: {build: {behind: 2, label: 'beta'}}}, 'build-current': {state: {build: {behind: 0, label: 'current'}}},
  'build-unknown': {state: {build: {label: 'unknown'}}}, 'build-label': {state: {build: {behind: -1, reloadLabel: 'Reload now'}}},
  'claude-options': {state: {connection: {connected: true, app: true}, claudeAsk: {help: true, always: true, auto: true, consent: true, takeover: false}, session: {stuck: 'Help'}}},
  tailor: {state: {connection: {connected: true, app: true}, session: {}, cv: {tailored: false}}},
};
for (const page of ['', 'reading', 'other', 'posting', 'opening', 'signing-in', 'signing-up', 'account', 'sign-up', 'unknown']) {
  cases[`page-${page || 'unset'}`] = {attrs: {page: page || null}};
  cases[`working-${page || 'unset'}`] = {attrs: {page: page || null}, state: {applyWorking: true}};
}
for (const state of ['missing', 'draft', 'invalid', 'unknown', 'ready']) {
  cases[`letter-${state}`] = {state: {coverLetterStatus: {state, ready: state === 'ready', reason: 'Status reason'}},
    prepare: p => p.document.getElementById('a').setAttribute('data-jobadabra-letter', '1')};
}
for (const kind of ['manual', 'manual-hidden', 'manual-error', 'rejected', 'given', 'account', 'moved']) {
  cases[`letter-${kind}`] = {state: {moved: kind === 'moved', coverLetterStatus: {state: 'missing', ready: false}},
    prepare: p => { const el = p.document.getElementById('a');
      if (kind.startsWith('manual')) { el.setAttribute('data-jobadabra-letter-manual', '1'); if (kind === 'manual-error') el.setAttribute('data-jobadabra-letter-error', '1'); if (kind === 'manual-hidden') el.style.visibility = 'hidden'; }
      else { el.setAttribute('data-jobadabra-letter', '1'); if (kind === 'rejected') el.setAttribute('data-jobadabra-letter-error', '1'); }
      if (kind === 'account') account('secret')(p);
      if (kind === 'given') p.fields[0].filled = true;
    }};
}

test('every render state keeps the complete serialized DOM, returned facts and effect order', {skip: !JSDOM}, async () => {
  const actual = {};
  for (const [name, options] of Object.entries(cases)) {
    const p = await panel(options);
    try { actual[name] = capture(p, p.api.render()); } finally { p.close(); }
  }
  assert.deepEqual(actual, EXPECTED);
});

test('rendered controls keep their targets, propagation, busy labels and messages', {skip: !JSDOM}, async () => {
  const p = await panel({state: {filledOnce: true, session: {id: 's1'}, movedTab: 8, build: {behind: 1}},
    fields: d => baseFields(d, [{draft: 'outline'}])});
  try {
    p.api.render(); p.events.length = 0;
    const row = p.root.querySelector('.item');
    row.click();
    row.querySelector('.tag:not(.warn)').click();
    assert.deepEqual(plain(p.events), [['flash', 'a'], ['flash', 'a'], ['review', 'a']], 'review stops propagation to the row');
    const reload = p.root.querySelector('.reload'); reload.click();
    assert.equal(reload.disabled, true); assert.equal(reload.textContent, 'Reloading…');
    assert.deepEqual(p.messages.at(-1), {type: 'panelReload'});
    p.root.querySelector('.open-app').click();
    assert.equal(p.root.querySelector('.open-app').textContent, 'Opening…');
    await flush();
    assert.deepEqual(p.messages.at(-1), {type: 'panelOpenApp', session: 's1'});
    p.api.set({moved: true, movedTab: 8}); p.api.render(); p.root.querySelector('.go-there').click();
    assert.deepEqual(p.messages.at(-1), {type: 'panelGoTab', tab: 8});
  } finally { p.close(); }
});

test('letter actions open setup or focus the rejected control; password requests remain throttled', {skip: !JSDOM}, async () => {
  const p = await panel({state: {coverLetterStatus: {state: 'missing', ready: false}}, prepare: q => {
    q.document.getElementById('a').setAttribute('data-jobadabra-letter', '1'); account('')(q);
  }});
  try {
    p.api.render(); p.api.render();
    assert.equal(p.messages.filter(m => m.type === 'sitePassword').length, 1);
    p.advance(2001); p.api.render();
    assert.equal(p.messages.filter(m => m.type === 'sitePassword').length, 2);
    const action = p.root.querySelector('.letter-action'); action.click();
    assert.equal(action.textContent, 'Opening…'); assert.equal(action.disabled, true);
    await flush();
    assert.equal(action.disabled, false); assert.equal(action.textContent, 'Create in Profile');
    assert.deepEqual(p.messages.at(-1), {type: 'panelOpenApp', session: 'setup:cover-letter'});
    p.document.getElementById('a').setAttribute('data-jobadabra-letter-error', '1');
    p.api.render(); p.events.length = 0; action.click();
    assert.deepEqual(plain(p.events), [['flash', 'a']]);
  } finally { p.close(); }
});

test('mark transitions, minimization and stopped/done states keep the same DOM across redraws', {skip: !JSDOM}, async () => {
  const p = await panel({state: {applyWorking: true, userMoved: false, open: false}, attrs: {page: 'reading'}});
  try {
    const actual = [];
    for (const mark of ['reading', 'posting', 'form']) { p.document.documentElement.setAttribute('data-jobadabra-page', mark); p.events.length = 0; actual.push(capture(p, p.api.render())); }
    p.root.querySelector('.min').click(); p.events.length = 0; actual.push(capture(p, p.api.render()));
    p.api.stoppedHere(); p.events.length = 0; actual.push(capture(p, p.api.render()));
    p.api.endStep(); p.events.length = 0; actual.push(capture(p, p.api.render()));
    assert.deepEqual(actual, TRANSITIONS);
  } finally { p.close(); }
});
